extern "C" __attribute__((visibility("default"))) ailo_status
ailo_ggml_backend_dev_caps_array_new(size_t count,
                                     struct ailo_ggml_backend_dev_caps **output,
                                     ailo_error *error) {
  if (!output)
    return ailo_error_set(error, AILO_INVALID_ARGUMENT,
                          "Result output is required");
  *output = {};
  return ailo::detail::native_boundary(error, [&]() {
    if (count > static_cast<size_t>(std::numeric_limits<ptrdiff_t>::max()) /
                    sizeof(struct ggml_backend_dev_caps))
      throw ailo::detail::native_range();
    if (count)
      *output = reinterpret_cast<struct ailo_ggml_backend_dev_caps *>(
          new struct ggml_backend_dev_caps[count]());
  });
}
extern "C" __attribute__((visibility("default"))) ailo_status
ailo_ggml_backend_dev_caps_array_free(struct ailo_ggml_backend_dev_caps *self,
                                      ailo_error *error) {
  return ailo::detail::native_boundary(error, [&]() {
    delete[] reinterpret_cast<struct ggml_backend_dev_caps *>(self);
  });
}
extern "C" __attribute__((visibility("default"))) ailo_status
ailo_ggml_backend_dev_caps_array_at(struct ailo_ggml_backend_dev_caps *self,
                                    size_t count, size_t index,
                                    struct ailo_ggml_backend_dev_caps **output,
                                    ailo_error *error) {
  if (!output)
    return ailo_error_set(error, AILO_INVALID_ARGUMENT,
                          "Result output is required");
  *output = {};
  if (!self)
    return ailo_error_set(error, AILO_INVALID_ARGUMENT,
                          "Native-backed record or storage is required");
  return ailo::detail::native_boundary(error, [&]() {
    if (index >= count)
      throw ailo::detail::native_range();
    *output = reinterpret_cast<struct ailo_ggml_backend_dev_caps *>(
        reinterpret_cast<struct ggml_backend_dev_caps *>(self) + index);
  });
}
